const con = parsePortableExecutable(createDemoPe('console'));
if (gui.subsystem !== 'windows-gui') throw new Error('GUI subsystem failed');
if (con.subsystem !== 'windows-console') throw new Error('Console subsystem failed');
console.log(JSON.stringify({ ok: true, gui: gui.subsystem, con: con.subsystem, sections: con.sections.length }));
